<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Baza danych'; ?>
<div class="page-head"><div><p class="eyebrow">Administracja · System</p><h1>Baza danych</h1></div></div>
<section class="card"><dl class="system-list"><dt>Serwer DB</dt><dd><?=Html::e($dbVersion)?></dd><dt>Baza</dt><dd><?=Html::e($database)?></dd><dt>Prefix tabel</dt><dd><?=Html::e($prefix?:'(brak)')?></dd><dt>Liczba tabel</dt><dd><?=$tables?></dd><dt>Pending migrations</dt><dd><?=count($pending)?></dd><dt>Cache</dt><dd><?=$cache['writable']?'OK':'Error'?> · <?=$cache['entries']?> wpisów · <?=number_format($cache['bytes']/1024,1)?> KiB</dd></dl></section>
